package ociresources

import (
	"time"

	"github.com/anthnel/devdesk/internal/cache"
)

// AddRegistryTags incorporates results from one registry into the combined tag list.
// Always decrements pendingSearches, even on error (tags will be nil).
func (b *RegistryBrowser) AddRegistryTags(entryKey, registryURL, alias, repo string, tags []string) {
	// Floored: a duplicate or late response would otherwise drive the counter
	// negative, and the next search would start from that base — IsSearching()
	// would stay false while requests were genuinely in flight, so the spinner
	// never showed.
	if b.pendingSearches > 0 {
		b.pendingSearches--
	}
	for _, tag := range tags {
		b.tags = append(b.tags, MultiRegistryTag{
			EntryKey:    entryKey,
			RegistryURL: registryURL,
			Alias:       alias,
			Repo:        repo,
			Tag:         tag,
		})
	}
	if b.state == browserStateTags {
		b.rebuildTagTable()
	}
}

// SetMultiTagsMeta stores last-updated metadata for tags belonging to one entry.
//
// Keyed on the entry, not the host: several entries share one host once a
// registry is a host plus a repo prefix, so a URL would stamp one proxy's dates
// onto every proxy of that instance (§3.18).
func (b *RegistryBrowser) SetMultiTagsMeta(entryKey string, meta map[string]time.Time) {
	for i := range b.tags {
		if b.tags[i].EntryKey != entryKey {
			continue
		}
		if t, ok := meta[b.tags[i].Tag]; ok {
			b.tags[i].UpdatedAt = t
		}
	}
	if b.state == browserStateTags {
		b.rebuildTagTable()
	}
}

// SetTagScanningSet replaces the in-progress scans the tag rows decorate.
//
// A set rather than one name at a time: the source is the registry snapshot,
// which says what is running rather than what changed, and reconciling a whole
// answer against per-name edits is how the two drift.
func (b *RegistryBrowser) SetTagScanningSet(scanning map[string]bool) {
	b.scanningTags = scanning
	if b.state == browserStateTags {
		b.rebuildTagTable()
	}
}

// HasSelectedTagScanResults returns true when the selected tag has cached scan results.
func (b *RegistryBrowser) HasSelectedTagScanResults() bool {
	name := b.selectedImageName()
	if name == "" {
		return false
	}
	_, ok := b.scanCache[name]
	return ok
}

// SetScanCache stores the model's scan cache for CVE column display.
func (b *RegistryBrowser) SetScanCache(sc map[string]cache.ImageScanEntry) {
	b.scanCache = sc
	if b.state == browserStateTags {
		b.rebuildTagTable()
	}
}

// SetOperationError, SetOperationSuccess and OperationImageName went with the
// status screen (§3.60): the browser is closed by the time a pull answers, and
// the answer goes to the footer and the Images list.

// selectedImageName returns the full image reference for the focused table row.
func (b *RegistryBrowser) selectedImageName() string {
	t := b.getSelectedMultiTag()
	if t == nil {
		return ""
	}
	return multiImageName(t.RegistryURL, t.Repo, t.Tag)
}

// getSelectedMultiTag returns the MultiRegistryTag under the cursor, or nil.
//
// It used to replay the filter and the sort to map the cursor back to a tag,
// with nothing tying that ordering to the one the rows were built from. The
// table keeps the ordered slice it drew, so the two cannot disagree.
func (b *RegistryBrowser) getSelectedMultiTag() *MultiRegistryTag {
	row, ok := b.tagTable.Selected()
	if !ok {
		return nil
	}
	return &row.tag
}
package ociresources

import (
	"strings"

	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// rebuildTagTable re-decorates the rows and hands them to the table.
//
// The decoration — the scan counts, whether a scan is running, the registry's
// label — is not on the tag, and the columns are built once so they cannot
// reach the browser for it. So it is recomputed wholesale on every change,
// exactly as the images tab does with imageRow.
//
// The filters are applied here because they narrow the tags before the table
// sees them; the sort and the header arrows are the table's.
func (b *RegistryBrowser) rebuildTagTable() {
	tags := b.filteredMultiTags()
	frame := spinner.Dot.Frames[b.tagScanSpinnerIdx%len(spinner.Dot.Frames)]

	rows := make([]tagRow, len(tags))
	for i, t := range tags {
		imageName := multiImageName(t.RegistryURL, t.Repo, t.Tag)
		label := t.Alias
		if label == "" {
			label = t.RegistryURL
		}
		entry, scanned := b.scanCache[imageName]
		rows[i] = tagRow{
			tag:      t,
			label:    label,
			entry:    entry,
			scanned:  scanned,
			scanning: b.scanningTags[imageName],
			frame:    frame,
		}
	}

	b.tagTable.SetItems(rows)
	b.resizeTagTable()
}

// View renders the browser for the current state.
func (b *RegistryBrowser) View() string {
	switch b.state {
	case browserStateTags:
		return b.viewTags()
	default:
		return b.viewInput()
	}
}

func (b *RegistryBrowser) viewInput() string {
	var sb strings.Builder

	sb.WriteString(theme.EmptyLineBg(b.width) + "\n")
	sb.WriteString(b.renderInputField("Repository", b.repoInput.View(), brFieldRepo))
	sb.WriteString("\n\n")

	if len(b.rows) > 0 {
		sb.WriteString(theme.Bg("  ") + theme.DimStyle.Render("Registries:") + "\n")
		for i, row := range b.rows {
			focused := b.focusedField == b.brFieldReg(i)
			if row.groupSlug != "" {
				// One checkbox for the whole group, with a third state for a
				// partial selection — eight proxies are not eight keystrokes.
				sb.WriteString(theme.RenderCheckboxTri(b.groupState(row.groupSlug), row.label, focused))
			} else {
				sb.WriteString(theme.RenderCheckbox(b.selected(b.entries[row.entry]), row.label, focused))
			}
			if i < len(b.rows)-1 {
				sb.WriteString("\n")
			}
		}
		sb.WriteString("\n\n")
	}

	sb.WriteString("  ")
	sb.WriteString(theme.RenderButton("Browse Tags", b.focusedField == b.brFieldSubmit(), "primary"))

	return sb.String()
}

func (b *RegistryBrowser) renderInputField(label, value string, fieldIdx int) string {
	var labelStr string
	if b.focusedField == fieldIdx {
		labelStr = theme.KeyStyle.Render(theme.IconCircleSmall + " " + label + " " + theme.IconChevronRight)
	} else {
		labelStr = theme.Bg("  " + label + " " + theme.IconChevronRight)
	}
	return labelStr + "\n  " + value
}

// viewTags renders the tag table. The search says so in the footer, with a
// spinner (LoadingLabel), and an empty table stays a table (Rule 139) — the
// count lives in GetHeaderInfo's "Tags" field.
func (b *RegistryBrowser) viewTags() string {
	return b.tagTable.View()
}

// LoadingLabel names what the browser is fetching, for the OCI view's footer.
// The second result is false when nothing is in flight.
func (b *RegistryBrowser) LoadingLabel() (string, bool) {
	if b.state == browserStateTags && b.pendingSearches > 0 {
		return "Searching registries...", true
	}
	return "", false
}

// FilterIsVisible returns true when the tag filter bar should be shown in the footer.
func (b *RegistryBrowser) FilterIsVisible() bool {
	return b.state == browserStateTags && (b.filterActive || b.filterInput.Value() != "" || !b.registryFilter.isEmpty())
}

// FilterBarView renders the filter bar (2 lines) for display in the footer.
func (b *RegistryBrowser) FilterBarView(width int) string {
	borderStyle := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)

	var left string
	if b.filterActive {
		left = theme.KeyStyle.Render("/") + theme.Bg(" ") + b.filterInput.View()
	} else if b.filterInput.Value() != "" {
		left = theme.DimStyle.Render("/ ") + theme.KeyStyle.Render(b.filterInput.Value())
	} else {
		left = theme.DimStyle.Render("/ filter…")
	}

	if !b.registryFilter.isEmpty() {
		left += theme.Bg("  ") + theme.KeyStyle.Render("["+b.registryFilterLabel()+"]")
	}

	inner := theme.Bg(" ") + left
	paddedInner := theme.PadWithBg(inner, width-2)
	contentLine := borderStyle.Render("│") + paddedInner + borderStyle.Render("│")
	bottomBorder := borderStyle.Render("└" + strings.Repeat("─", width-2) + "┘")
	return contentLine + "\n" + bottomBorder
}

// viewStatus is gone with browserStateStatus (§3.60). It was a
// theme.SpinnerMessage filling the panel — the shape Rule 139 keeps out of a
// table body — and what it announced is now a row in the Images tab.
package ociresources

import (
	"strings"

	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/docker"
	"github.com/anthnel/devdesk/internal/ui/keymap"
)

// InEditMode returns true when a text input is active (blocks command mode).
func (b *RegistryBrowser) InEditMode() bool {
	if b.state == browserStateInput && b.focusedField == brFieldRepo {
		return true
	}
	return b.state == browserStateTags && b.filterActive
}

// IsSearching returns true while registry tag queries are still in flight.
func (b *RegistryBrowser) IsSearching() bool {
	return b.pendingSearches > 0
}

// Update handles all messages for the browser.
func (b *RegistryBrowser) Update(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.KeyMsg:
		return b.handleKeyMsg(msg)
	case spinner.TickMsg:
		if len(b.scanningTags) > 0 || b.pendingSearches > 0 {
			var cmd tea.Cmd
			b.spinner, cmd = b.spinner.Update(msg)
			if b.state == browserStateTags && len(b.scanningTags) > 0 {
				b.tagScanSpinnerIdx++
				b.rebuildTagTable()
			}
			return b, cmd
		}
		return b, nil
	}
	return b.delegateUpdate(msg)
}

func (b *RegistryBrowser) delegateUpdate(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
	if b.state == browserStateInput && b.focusedField == brFieldRepo {
		var cmd tea.Cmd
		b.repoInput, cmd = b.repoInput.Update(msg)
		return b, cmd
	}
	if b.state == browserStateTags {
		if b.filterActive {
			var cmd tea.Cmd
			b.filterInput, cmd = b.filterInput.Update(msg)
			b.rebuildTagTable()
			return b, cmd
		}
		return b, b.tagTable.Update(msg)
	}
	return b, nil
}

func (b *RegistryBrowser) handleKeyMsg(msg tea.KeyMsg) (*RegistryBrowser, tea.Cmd) {
	switch b.state {
	case browserStateInput:
		return b.handleInputKeyMsg(msg)
	case browserStateTags:
		return b.handleTagsKeyMsg(msg)
	}
	return b, nil
}

func (b *RegistryBrowser) handleInputKeyMsg(msg tea.KeyMsg) (*RegistryBrowser, tea.Cmd) {
	switch msg.String() {
	case "esc":
		return b, func() tea.Msg { return RegistryBrowserCloseMsg{} }
	case "down":
		b.focusedField = min(b.focusedField+1, b.brFieldSubmit())
		b.updateFocus()
		return b, nil
	case "up":
		b.focusedField = max(b.focusedField-1, brFieldRepo)
		b.updateFocus()
		return b, nil
	case " ":
		if b.focusedField >= 1 && b.focusedField <= len(b.rows) {
			row := b.rows[b.focusedField-1]
			if row.groupSlug != "" {
				b.toggleGroup(row.groupSlug)
				return b, nil
			}
			key := b.entries[row.entry].key
			b.selectedRegs[key] = !b.selectedRegs[key]
			return b, nil
		}
	case "enter":
		if b.focusedField == brFieldRepo || b.focusedField == b.brFieldSubmit() {
			return b.submitSearch()
		}
		b.focusedField = min(b.focusedField+1, b.brFieldSubmit())
		b.updateFocus()
		return b, nil
	}
	return b.delegateUpdate(msg)
}

// credsFor returns the credentials to search entry with, and nothing at all
// when the registry — or the group it belongs to — is marked anonymous (D12).
// Docker keys credentials by host, so a Nexus instance with one repository
// logged into would otherwise send that login to every repository it serves.
func (b *RegistryBrowser) credsFor(entry browserRegistryEntry) (string, string) {
	if !config.UsesCredentials(entry.authMode) {
		return "", ""
	}
	// Credentials come from the parent registry, or the entry itself for a
	// registry that is not a group member.
	credURL := entry.URL
	if entry.parentURL != "" {
		credURL = entry.parentURL
	}
	var username string
	for _, reg := range b.registries {
		if reg.URL == credURL {
			username = reg.Username
			break
		}
	}
	storedUser, storedPass, _ := docker.GetStoredCreds(credURL)
	if username == "" {
		username = storedUser
	}
	return username, storedPass
}

func (b *RegistryBrowser) submitSearch() (*RegistryBrowser, tea.Cmd) {
	repo := strings.TrimSpace(b.repoInput.Value())
	if repo == "" {
		return b, nil
	}

	b.tags = nil
	b.registryFilter = resultFilter{}
	b.pendingSearches = 0
	b.filterInput.SetValue("")
	b.filterActive = false
	// A new search starts from the default order, not wherever the last one's
	// `.` presses left the table.
	b.tagTable.SetSort(tagColumnTag, false)

	var cmds []tea.Cmd
	for _, entry := range b.entries {
		if !b.selected(entry) {
			continue
		}
		username, storedPass := b.credsFor(entry)
		alias := entry.Alias
		if entry.ParentAlias != "" {
			alias = entry.ParentAlias + "/" + entry.Alias
		}
		// The prefix is applied here and nowhere else: it is then already part
		// of MultiRegistryTag.Repo, so multiImageName and registryAPIURL need to
		// know nothing about it. Teaching both would be two places free to
		// drift, which is the disagreement D39 already is (§3.18).
		normalizedRepo := joinRepoPrefix(entry.repoPrefix, normalizeRepoForRegistry(entry.URL, repo))
		apiURL := registryAPIURL(entry.URL)
		b.pendingSearches++
		cmds = append(cmds, searchRegistryTagsCmd(entry.key, entry.URL, alias, apiURL, normalizedRepo, username, storedPass))
	}

	if len(cmds) == 0 {
		return b, nil
	}

	b.state = browserStateTags
	b.tagTable.Focus()
	b.rebuildTagTable()
	cmds = append(cmds, b.spinner.Tick)
	return b, tea.Batch(cmds...)
}

func (b *RegistryBrowser) handleTagsKeyMsg(msg tea.KeyMsg) (*RegistryBrowser, tea.Cmd) {
	if b.filterActive {
		switch msg.String() {
		case "esc", "enter":
			b.filterActive = false
			b.filterInput.Blur()
			b.rebuildTagTable()
			b.resizeTagTable()
			return b, nil
		}
		return b.delegateUpdate(msg)
	}

	switch msg.String() {
	case "esc":
		b.state = browserStateInput
		b.tagTable.Blur()
		b.updateFocus()
		return b, nil
	case "/":
		b.filterActive = true
		b.filterInput.Focus()
		b.resizeTagTable()
		return b, nil
	case "r":
		b.cycleRegistryFilter()
		return b, nil
	case "enter":
		return b.openTagScanDetails()
	case keymap.Get:
		return b.pullSelectedTag()
	case keymap.Scan:
		return b.requestDirectScan()
	}
	// Navigation and `.` are the table's. `/` never reaches it: the browser's
	// own filter took the key two cases above, and the table declares no
	// searchable column, so it would decline it anyway.
	return b, b.tagTable.Update(msg)
}
package ociresources

import (
	"slices"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/docker"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/indicator"
	"github.com/anthnel/devdesk/internal/ui/registryalias"
)

// What is being scanned is the registry's answer, not this view's (§3.58).
//
// It held a `scanningImages` map and a `scanning` bool derived from it, and both
// knew only what this view had launched. An image scanned from `:sec` — the same
// image, the same cache entry — went unnoticed here, so `S` offered itself on a
// row already being scanned and the two wrote the same file.
//
// The view's own `spinner.Model` stays, and deliberately: it animates *loading*
// — the image list, the networks, a `docker` action on a row — and a load is not
// a job. What moved is the blink phase of the activity column, which comes from
// the one chain the router holds (D5).

// handleJobsChanged takes the router's snapshot. It is the only writer of the
// two fields.
func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
	m.jobs = msg.Runs
	m.failures = slices.Clone(msg.Failures)
	m.contextName = msg.Context
	// The footer's spinner is deliberately not touched: here it belongs to
	// *loading* — a tab reading its list — and this view's scan progress is on
	// the rows, not in the footer. Two writers of one field would fight every
	// frame a scan and a load overlapped.
	m.updateImageTable()
	if m.registryBrowser != nil {
		m.registryBrowser.SetTagScanningSet(m.scanningNames())
	}
	return m, nil
}

// handleFrameMsg takes the blink phase of the activity column. Nothing is
// rebuilt: the table reads the phase at render. The footer frame is the
// router's only while no tab load is running: the view's own spinner owns it
// then, and two writers would fight every frame.
func (m Model) handleFrameMsg(msg jobs.FrameMsg) (tea.Model, tea.Cmd) {
	m.imageTable.SetBlinkPhase(msg.Blink)
	m.networkTable.SetBlinkPhase(msg.Blink)
	m.volumeTable.SetBlinkPhase(msg.Blink)
	m.registryTable.SetBlinkPhase(msg.Blink)
	if !m.loading && !m.loadingNets && !m.loadingVols && !m.loadingRegs {
		m.footer.SetSpinnerFrame(msg.RenderedFrame)
	}
	return m, nil
}

// WantsBlink reports whether an Images row is in an animated state (running,
// or an action observed on it). A queued row and a remembered failure are
// steady. It is the level the router's BlinkingView check reads.
func (m Model) WantsBlink() bool {
	for _, r := range m.imageTable.Items() {
		if r.Activity.State == indicator.Running {
			return true
		}
	}
	// A busy row (network, volume, registry) and a group being discovered both
	// show a blinking dot.
	return len(m.refreshingGroups) > 0 ||
		len(m.networkTable.BusyLabels()) > 0 ||
		len(m.volumeTable.BusyLabels()) > 0 ||
		len(m.registryTable.BusyLabels()) > 0
}

// scanRun builds the run behind S, A, ctrl+a and a direct scan from the browser.
func (m Model) scanRun(names []string) jobs.Run {
	run := jobs.NewRun(jobs.KindScan, command.ViewOCIResources, "", "images", names...)
	// The alias is applied here rather than by whoever shows the run: it is
	// this view's configuration that defines it, and `:jobs` has no business
	// reading a registry list to print a name.
	aliases := registryalias.From(m.registries)
	for _, name := range names {
		if display := docker.ApplyAliases(name, aliases); display != name {
			run = run.WithDisplay(name, display)
		}
	}
	return run
}

// scanningImage reports whether an image is queued or being scanned, whoever
// started it.
func (m Model) scanningImage(name string) bool {
	for _, run := range jobs.Unfinished(m.jobs) {
		if run.Kind != jobs.KindScan {
			continue
		}
		for _, item := range run.Items {
			if item.Target == name && !item.State.Terminal() {
				return true
			}
		}
	}
	return false
}

// scanningNames lists every image with a scan in flight, for the registry
// browser, which decorates its tag rows from the same source.
func (m Model) scanningNames() map[string]bool {
	out := make(map[string]bool)
	for _, run := range jobs.Unfinished(m.jobs) {
		if run.Kind != jobs.KindScan {
			continue
		}
		for _, item := range run.Items {
			if !item.State.Terminal() {
				out[item.Target] = true
			}
		}
	}
	return out
}

// anyScanRunning reports whether a scan is going anywhere. It is what A and
// ctrl+a refuse on, and it is true for a scan this view did not start — which
// is the point: the two would write the same cache entries.
func (m Model) anyScanRunning() bool { return len(m.scanningNames()) > 0 }

// pullRun builds the run behind a registry-browser pull.
func (m Model) pullRun(name string) jobs.Run {
	run := jobs.NewRun(jobs.KindPull, command.ViewOCIResources, "", "images", name)
	aliases := registryalias.From(m.registries)
	if display := docker.ApplyAliases(name, aliases); display != name {
		run = run.WithDisplay(name, display)
	}
	return run
}

// pullingImage reports whether a pull for name is queued or running.
func (m Model) pullingImage(name string) bool {
	for _, run := range jobs.Unfinished(m.jobs) {
		if run.Kind != jobs.KindPull {
			continue
		}
		for _, item := range run.Items {
			if item.Target == name && !item.State.Terminal() {
				return true
			}
		}
	}
	return false
}

// pullingNames lists every image with a pull in flight, for imageRows —
// which is what shows a placeholder row for an image not pulled before.
func (m Model) pullingNames() map[string]bool {
	out := make(map[string]bool)
	for _, run := range jobs.Unfinished(m.jobs) {
		if run.Kind != jobs.KindPull {
			continue
		}
		for _, item := range run.Items {
			if !item.State.Terminal() {
				out[item.Target] = true
			}
		}
	}
	return out
}

// ── What each message tells the registry (jobs.Reporter) ─────────────────────

func (m ImageScanStartingMsg) Transition() jobs.Transition {
	return jobs.Transition{Kind: jobs.KindScan, Target: m.ImageName, State: jobs.ItemRunning, Cancel: m.Cancel}
}

func (m ImageScanFinishedMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindScan, Target: m.ImageName, State: jobs.ItemDone}
	if m.Err != nil {
		t.State = jobs.ItemFailed
		t.Detail = "scan failed — check logs"
	}
	return t
}

func (m RegistryPullStartingMsg) Transition() jobs.Transition {
	return jobs.Transition{Kind: jobs.KindPull, Target: m.ImageName, State: jobs.ItemRunning, Cancel: m.Cancel}
}

func (m RegistryPullCompleteMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindPull, Target: m.ImageName, State: jobs.ItemDone}
	switch {
	case len(m.InUse) > 0:
		t.State = jobs.ItemFailed
		t.Detail = "not updated — the image is in use"
	case isBlocked(m.Err):
		// The reason, not "check logs": it names the rule, and it is what an
		// agent that asked for the pull reads (§3.82).
		t.State = jobs.ItemFailed
		t.Detail = "refused — " + m.Err.Error()
	case m.Err != nil:
		t.State = jobs.ItemFailed
		t.Detail = "pull failed — check logs"
	}
	return t
}

// Compile-time proof that every progress message can be applied. One added
// without a transition would leave its row spinning for the life of the view.
var (
	_ jobs.Reporter = ImageScanStartingMsg{}
	_ jobs.Reporter = ImageScanFinishedMsg{}
	_ jobs.Reporter = RegistryPullStartingMsg{}
	_ jobs.Reporter = RegistryPullCompleteMsg{}
)
package ociresources

import (
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/indicator"
)

// ociKinds are the operations whose activity or remembered failure an Images
// row shows: a scan or a pull, whoever started it (D5).
var ociKinds = []jobs.Kind{jobs.KindScan, jobs.KindPull}

// rowActivity resolves what one Images row says about its activity, read from
// the router snapshot against the context it carries. The identity is the raw
// reference, never a canonical form. A removal in flight is this view's own
// observation: it is reported as Running with its label.
func (m Model) rowActivity(r imageRow) components.RowActivity {
	q := components.RowQuery{
		Runs: m.jobs, Failures: m.failures, Context: m.contextName,
		Target: jobs.TargetKey(r.RawName), Kinds: ociKinds,
	}
	if label, ok := m.imageTable.BusyLabel(r.Image.ID); ok {
		q.Observed = indicator.Running
		q.ObservedText = label
	}
	return components.DescribeRow(q)
}

// scanRunning reports whether a scan of the image is running now in the
// current context. A queued scan is not running.
func (m Model) scanRunning(name string) bool { return m.runningOn(name, jobs.KindScan) }

// pullRunning reports whether a pull of the image is running now in the
// current context. A queued pull is not running.
func (m Model) pullRunning(name string) bool { return m.runningOn(name, jobs.KindPull) }

func (m Model) runningOn(name string, kind jobs.Kind) bool {
	for _, a := range jobs.ActiveOn(m.jobs, m.contextName, name, kind) {
		if a.Item.State == jobs.ItemRunning {
			return true
		}
	}
	return false
}

// ActivityTables returns the read-only face of the view's table, keyed by the
// name the activity-column guard (internal/app) knows it by. Tests only.
func (m Model) ActivityTables() map[string]datatable.ActivityTable {
	return map[string]datatable.ActivityTable{
		"oci/images":     &m.imageTable,
		"oci/networks":   &m.networkTable,
		"oci/volumes":    &m.volumeTable,
		"oci/registries": &m.registryTable,
	}
}

